import { isPage, STAMP } from './public/version.mjs';

// Being a public website, whatever serves it: the version the site carries and the
// stamp its pages show, and the ways a page that fetches its own data goes quietly
// stale. A hosting pack's release reaches `public/version.mjs` to advance the version
// as part of cutting a release, and goes out without a bump when the file is absent.
const carriesAStamp = (ctx) => ctx.tracked.some((f) => isPage(f) && new RegExp(STAMP.source).test(ctx.read(f) ?? ''));

export default {
  version: '60921.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'being a public website whatever serves it: the version scheme and page stamp, client-side caching and data freshness',
    excludes: 'how the site is built, served or released — the hosting pack declared beside this one; markup — html',
  },
  marker: 'a tracked page carrying a `title="version …"` stamp',
  detect: carriesAStamp,
  requires: ['html'],
};
=== context.test 555-580
// vendored — an un-adoption, silently, with a green run to show for it.
test('a pre-rename member loads identically to a converged one', () => {
  const root = mkdtempSync(join(tmpdir(), 'claudinite-config-legacy-'));
  try {
    writeFiles(root, {
      '.claudinite-checks.json': JSON.stringify({
        packs: ['acme-pack', { id: 'acme-pack-b', config: { k: 1 } }],
        maintenance: { delivery: 'review', mechanism: 'versioned' },
        claudinite: {
          updated: '2026-07-26T20:10:18.694Z',
          ref: 'deadbeef',
          engineVersion: '60820.1',
          // `tidy-repo` is a spelling `basics` absorbed: a version stamped under a
          // renamed pack's id must still price that pack, not read as never-installed.
          packVersions: { 'git-github': '60801.1', 'tidy-repo': '60802.1' }, // @real-entity the rename map under test carries these ids
        },
        taskScheduler: { endpoints: { default: { url: 'u', tokenSecret: 'S' } }, dailyHour: 4 },
      }, null, 2) + '\n',
    });
    const cfg = loadConfig(root);
    assert.deepEqual(cfg.errors, [], 'the retired shape is legal to READ — only nothing writes it');
    assert.deepEqual(cfg.packs, ['acme-pack', 'acme-pack-b']);
    assert.equal(cfg.engineVersion, '60820.1');
    assert.deepEqual(cfg.packVersions, { 'git-github': '60801.1', basics: '60802.1' }); // @real-entity the rename map under test carries these ids
    assert.equal(cfg.dailyClaudiniteUpdatesRequirePrReview, true, 'the retired delivery preference still speaks');
    assert.deepEqual(cfg.packConfig['acme-pack-b'], { k: 1 });
=== pack-renames-declaration record
// The declaration half of the 2026-08-19 pack renames (#1041), which the record
// beside it (2026-08-19-pack-renames) shipped broken.
//
// That record moved each member's mount directories and its stamped `packVersions`
// keys, and both landed. What it could not do was rewrite the `packs` array: it
// tried textually, anchored on `"packs": [` so a member's own `{ "from": "core" }`
// barrier rule could never be caught by accident, and a real packs array holds entry
// objects with nested arrays (`{ "id": "barriers", "via": ["basics"] }`) that the
// anchor could not cross. Every element after the first such object was invisible to
// it. Measured on the canary: engine, versions and mount all converged, the
// declaration did not.
//
// A SEPARATE RECORD rather than a repair of that one, because a record only applies
// while a repo sits below the version its change took effect at. The canary is
// already stamped 5, so the 5 record can never run there again — and a member that
// converged is exactly the member whose declaration still needs moving.
//
// NOTHING DEPENDED ON THIS HAVING RUN while the tolerance stood, as with its
// predecessor: the loader resolved both spellings, so a member read correctly whether
// or not its declaration had been converged. What it bought was the day
// `renamed-packs.mjs` could be retired for these ids, which is the only reason to
// converge a declaration nobody has to read — and that day came (#1641), so a member
// that never ran this record now activates nothing under either old spelling.
export default {
  id: 'pack-renames-declaration',
  landed: '2026-08-19',
  version: 6,
  summary: "the packs array is converged onto each renamed pack's current id (the 2026-08-19-pack-renames record moved the mount and the stamp but not the declaration)",

  // Structural, and the ids come from the engine's rename map rather than from this
  // record — see applyPackRenames in engine/migrations/registry.mjs.
  renameDeclaredPacks: true,
};

