296	const LEGACY_LOCAL_DECL = 'local_packs/';
297	
298	// Write side — "the packs this repo declares have been renamed": rewrite each
299	// `packs` entry whose id is a legacy spelling to the id that pack carries today.
300	// The ids come from the engine's own rename map, never from the record, so a future
301	// rename needs no new op and no record restating what the loader already knows.
302	//
303	// STRUCTURAL, NOT TEXTUAL, and that is the whole point of it. The first attempt at
304	// this was a regex over the declaration, anchored on `"packs": [` so it could not
305	// wander into a member's own `{ "from": "core" }` barrier rule. It could not wander
306	// anywhere at all: a real packs array holds entry objects with nested arrays
307	// (`{ "id": "barriers", "via": ["basics"] }`), the anchor could not cross a nested
308	// `]`, and every element after the first such object was invisible to it. Parsing
309	// removes both failures at once — the `packs` array is the only thing read, so a
310	// same-named key anywhere else in the file is never even seen (#1041).
311	//
312	// SEEDS NOTHING AND DROPS NOTHING, like the local-declaration normalization beside
313	// it: entry objects keep their config, answers, `via` and order; only the id token
314	// changes. A LOCAL declaration is skipped — that namespace is the repo's, so a local
315	// pack sharing a canon pack's old name is not this op's business. Idempotent, so a
316	// repo already converged is a no-op, and it patches the parsed declaration back with
317	// the same 2-space shape every other declaration writer here uses.
318	// Two entries that were different packs and are now the same one. A rename can
319	// merge two ids into one (a pack absorbed into another), and every member carrying
320	// the absorbed pack carries the absorbing one too when the first `requires` the
321	// second — so the collision is not an edge case there, it is every member.
322	//
323	// Dropping either side would drop what a member wrote: `config` answers it gave at
324	// adoption, `rules` severities it chose, `accept` entries standing against findings
325	// that would otherwise come back. So the two are MERGED. The survivor is the entry
326	// that appeared first, and its own values win a key conflict — the absorbed entry
327	// fills only what the survivor does not say. Arrays (`accept`, `rules`, `via`)
328	// concatenate, dropping an element the survivor already carries verbatim. An object
329	// absorbed into a plain-string entry promotes the survivor to an object: a string
330	// entry carries an id and nothing else, so keeping the string would be the one shape
331	// that silently discards the other side.
332	export function mergeDeclarationEntries(survivor, absorbed) {
333	  if (typeof absorbed === 'string') return survivor;
334	  const base = typeof survivor === 'string' ? { id: survivor } : { ...survivor };
335	  for (const [key, value] of Object.entries(absorbed)) {
336	    if (key === 'id') continue;
337	    const have = base[key];
338	    if (have === undefined) { base[key] = value; continue; }
339	    if (Array.isArray(have) && Array.isArray(value)) {
340	      const seen = new Set(have.map((v) => JSON.stringify(v)));
341	      base[key] = [...have, ...value.filter((v) => !seen.has(JSON.stringify(v)))];
342	      continue;
343	    }
344	    if (have && value && typeof have === 'object' && typeof value === 'object'
345	      && !Array.isArray(have) && !Array.isArray(value)) {
346	      base[key] = { ...value, ...have };
347	    }
348	    // Two scalars that disagree: the survivor's stands. It is the entry the member
349	    // wrote for the pack that still exists under its own name.
350	  }
351	  // `via` says which packs pulled this one in, and an absorbed pack's `via` can name
352	  // the very pack that absorbed it — leaving the survivor claiming it was required by
353	  // itself. Drop that, and where nothing but the id survives, write the entry back as
354	  // the bare string a member declaring a plain pack has.
355	  if (Array.isArray(base.via)) {
356	    const via = base.via.filter((v) => v !== base.id);
357	    if (via.length) base.via = via; else delete base.via;
358	  }
359	  return Object.keys(base).length === 1 ? base.id : base;
360	}
